#!/bin/sh
# Sets the non-secret values in .env. Secrets were generated by utils/generate-keys.sh.
set -e
cd /opt/tnportal/supabase
# Where people use the portal. Staging until the switch-over (migration plan,
# phase 6), then https://truenorthportal.online: the sign-in links in the
# emails follow it.
PORTAL_URL="${PORTAL_URL:-https://staging.truenorthportal.online}"
setv() { # setv KEY VALUE: replace the line, or append it
  if grep -q "^$1=" .env; then
    esc=$(printf '%s' "$2" | sed 's/[&|]/\\&/g')
    sed -i "s|^$1=.*|$1=$esc|" .env
  else
    printf '%s=%s\n' "$1" "$2" >> .env
  fi
}
setv COMPOSE_FILE docker-compose.yml:docker-compose.tnportal.yml
setv SUPABASE_PUBLIC_URL https://db.truenorthportal.online
setv API_EXTERNAL_URL https://db.truenorthportal.online/auth/v1
setv SITE_URL "$PORTAL_URL"
# Fetched by the sign-in service from the portal container over Docker's network
# (deploy/portal/docker-compose.yml); the public address refuses its client.
setv EMAIL_TEMPLATES_BASE http://tnportal-portal:3000/email-templates
setv ADDITIONAL_REDIRECT_URLS "https://truenorthportal.online/**,https://staging.truenorthportal.online/**,http://localhost:3000/**"
setv DISABLE_SIGNUP false
setv ENABLE_EMAIL_SIGNUP true
setv ENABLE_EMAIL_AUTOCONFIRM false
setv ENABLE_ANONYMOUS_USERS false
setv ENABLE_PHONE_SIGNUP false
setv ENABLE_PHONE_AUTOCONFIRM false
setv SMTP_ADMIN_EMAIL portal@truenorthportal.online
setv SMTP_HOST smtp.resend.com
setv SMTP_PORT 465
setv SMTP_USER resend
setv SMTP_SENDER_NAME "True North Operations Portal"
setv STUDIO_DEFAULT_ORGANIZATION "True North Digital Marketing"
setv STUDIO_DEFAULT_PROJECT "Operations Portal"
setv DASHBOARD_USERNAME truenorth
setv OPENAI_API_KEY ""
# Only on this machine: LiteSpeed forwards the public address to it.
setv API_GW_HTTP_PORT 127.0.0.1:8000
setv KONG_HTTP_PORT 127.0.0.1:8000
grep -E "^(COMPOSE_FILE|SUPABASE_PUBLIC_URL|API_EXTERNAL_URL|SITE_URL|EMAIL_TEMPLATES_BASE|ADDITIONAL_REDIRECT_URLS|ENABLE_PHONE_SIGNUP|SMTP_HOST|SMTP_PORT|SMTP_USER|SMTP_SENDER_NAME|API_GW_HTTP_PORT|DASHBOARD_USERNAME)=" .env
